{
  "findings": [
    {
      "check_id": "AVD-AWS-0067",
      "title": "Lambda permission lacks source ARN for API Gateway principal",
      "resource": "aws_lambda_permission.api_gateway_invoke",
      "severity": "CRITICAL",
      "explanation": "The Lambda permission allows invocation by 'apigateway.amazonaws.com' without restricting the source ARN. This permits any API Gateway resource in any AWS account to invoke this function, leading to potential unauthorized access or abuse."
    }
  ],
  "patched_code": "resource \"aws_lambda_permission\" \"api_gateway_invoke\" {\n  statement_id  = \"AllowExecutionFromAPIGateway\"\n  action        = \"lambda:InvokeFunction\"\n  function_name = aws_lambda_function.log_processing_pipeline.function_name\n  principal     = \"apigateway.amazonaws.com\"\n  source_arn    = \"${aws_apigatewayv2_api.my_api.execution_arn}/*/*\"\n}",
  "fix_summary": "Added a `source_arn` attribute to the `aws_lambda_permission` resource to restrict invocation to a specific API Gateway stage and route, preventing cross-account or unauthorized invocations."
}
